#imip-view-toolbar > .toolbarbutton-1[is="toolbarbutton-menu-button"] {
  border-radius: var(--button-border-radius);
}

#imip-view-toolbar > .toolbarbutton-1.message-header-view-button {
  -moz-context-properties: fill, stroke;
  fill: color-mix(in srgb, currentColor 20%, transparent);
  stroke: currentColor;
  margin-inline-start: 6px;
  background-image: var(--imip-button-background);
  border-color: var(--toolbarbutton-header-bordercolor);

  &:not(.imipMoreButton, :active):hover {
    background-image: var(--imip-button-background-hover);
  }

  &:not([is="toolbarbutton-menu-button"], .imipMoreButton):hover:active {
    background-image: var(--imip-button-background-active);
  }
